file.content:
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #2a2622;
  background: #fffdf9;
}

a {
  color: inherit;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 64px;
  border-bottom: 1px solid #ece6dc;
}

.logo {
  font-size: 20px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  align-items: center;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  color: #5c544b;
}

.site-nav .nav-signin {
  padding: 10px 22px;
  border-radius: 6px;
  background: #8a3b24;
  color: #ffffff;
  font-weight: 500;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 64px;
  padding: 64px 64px 48px;
}

.hero-text {
  max-width: 540px;
}

h1 {
  margin: 0 0 16px;
  font-size: 40px;
  font-weight: 500;
  line-height: 1.15;
}

.hero-text p {
  margin: 0 0 28px;
  color: #5c544b;
}

.actions {
  display: flex;
  gap: 12px;
}

.button {
  display: inline-block;
  padding: 10px 18px;
  border-radius: 6px;
  text-decoration: none;
  font-size: 15px;
}

.button-primary {
  border: 1px solid #d6cec2;
  background: #f3eee6;
  color: #5c544b;
}

.button-secondary {
  border: 1px solid #d6cec2;
  background: #fffdf9;
  color: #5c544b;
}

.preview {
  flex: 0 0 480px;
  border: 1px solid #ece6dc;
  border-radius: 8px;
  background: #ffffff;
}

.preview-head {
  display: flex;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid #ece6dc;
  font-weight: 500;
}

.preview-date {
  color: #8a8178;
  font-weight: 400;
  font-size: 14px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

th,
td {
  padding: 9px 18px;
  text-align: left;
  border-bottom: 1px solid #f3eee6;
}

th {
  color: #8a8178;
  font-weight: 400;
}

tbody tr:last-child td {
  border-bottom: none;
}

.facts {
  display: flex;
  gap: 40px;
  padding: 8px 64px 0;
}

.facts p {
  flex: 1;
  margin: 0;
  font-size: 15px;
  color: #5c544b;
}

.fact-title {
  color: #2a2622;
  font-weight: 500;
}

content.content:
{"rank":1,"title":"The layout does not reflow below desktop width","sel":"h1","target":"page width equals the viewport width with no sideways scroll; headline, paragraph, buttons, table and notes stacked in one column; text at 45 to 75 characters per line where the width allows","fix_direction":"Below a breakpoint, stack the page into one column (headline, paragraph, buttons, then the table at full width, then the notes one under another), and collapse or simplify the navigation so it fits the width."}
{"rank":2,"title":"\"Sign in\" is styled as the primary action and the trial button is not","sel":"a.button.button-primary","target":"one high-emphasis action: the trial button filled rust, \"Sign in\" a text link or outline button","fix_direction":"Give the trial button the filled rust treatment, and drop \"Sign in\" to a text link or an outline button in the nav."}
{"rank":3,"title":"On wide screens the page falls apart into two edges and an empty floor","sel":"h1","target":"content held to a centered container about the width of the desktop layout; a closing section at the end of the page that repeats the trial ask","fix_direction":"Constrain the content to a centered container about the width of the desktop layout, so the headline and the table stay a glance apart. End the page with a closing section that repeats the trial ask, using what the nav already promises (\"Shops using it\", \"Pricing\") if that content exists."}
{"rank":4,"title":"The copy leaves out the facts a shop owner checks first","sel":"section.facts > p:nth-of-type(1)","target":"each note says which kind of system, distributor or actor it covers, and the page lets the owner compare Shelfmark with what they do now","fix_direction":"Name the kind of fact that is missing in each note: the tills and card readers it supports, the distributors it sends reorder lists to, and who tracks the returns, which the maker must supply. Let the bold lead-in of the returns note follow \"Unsold copies due back are listed by date\". The maker must also supply a comparison with what the owner does now, such as a stock count, a spreadsheet, or the till's own report."}
{"rank":null,"title":"The table headers and the date are under the 4.5:1 contrast minimum","sel":"thead > tr > th:nth-of-type(1)","target":"contrast of at least 4.5:1","fix_direction":"Darken the table headers and the date to the body gray #5c544b."}
{"rank":null,"title":"The type sizes 16, 15 and 14 px are 1 px apart","sel":null,"target":"one or two sizes in place of 16, 15 and 14 px, with levels separated by weight and color","fix_direction":"Fold the three sizes into one or two, and separate levels with weight and color."}
{"rank":null,"title":"The headline leaves \"asks\" alone on a third line","sel":"h1","target":"headline breaks at a phrase, with no single word alone on a line","fix_direction":"Rebalance the headline's measure so it breaks at a phrase, and check the second feature note on the widescreen for the same lone word."}
{"rank":null,"title":"The three feature columns line up with nothing in the hero above","sel":"section.facts > p:nth-of-type(2)","target":"the feature notes and the hero share one column grid, with at least one note edge matching the table's left edge","fix_direction":"Put both rows on one column grid."}
{"rank":null,"title":"On the widescreen the feature notes run 79 to 81 characters per line","sel":"section.facts > p:nth-of-type(2)","target":"75 characters per line or fewer","fix_direction":"A content max-width, as in the wide-screen finding, fixes this too."}

