input.content:
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #2a2622;
  background: #fffdf9;
}

a {
  color: inherit;
}

/* Holds every section to one centered width, so wide screens keep the
   headline and the table a glance apart. */
.site-header,
main {
  max-width: 1152px;
  margin: 0 auto;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px 28px;
  padding: 18px 64px;
}

.header-rule {
  border-bottom: 1px solid #ece6dc;
}

.logo {
  font-size: 20px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 28px;
}

.site-nav a {
  text-decoration: none;
  color: #5c544b;
  white-space: nowrap;
}

.site-nav .nav-signin {
  color: #2a2622;
  font-weight: 500;
}

/* The hero and the notes share one grid: two text columns, then a
   480 px column that holds the table, so the third note starts at the
   table's left edge. */
.hero,
.facts {
  display: grid;
  grid-template-columns: 1fr 1fr 480px;
  column-gap: 64px;
  padding-left: 64px;
  padding-right: 64px;
}

.hero {
  align-items: center;
  padding-top: 64px;
  padding-bottom: 56px;
}

.hero-text {
  grid-column: 1 / 3;
  max-width: 540px;
}

h1 {
  margin: 0 0 16px;
  font-size: 40px;
  font-weight: 500;
  line-height: 1.15;
  text-wrap: balance;
}

.hero-text p {
  margin: 0 0 28px;
  color: #5c544b;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.button {
  display: inline-block;
  padding: 10px 18px;
  border-radius: 6px;
  text-decoration: none;
  font-size: 16px;
  white-space: nowrap;
}

.button-primary {
  border: 1px solid #8a3b24;
  background: #8a3b24;
  color: #ffffff;
  font-weight: 500;
}

.button-secondary {
  border: 1px solid #d6cec2;
  background: #fffdf9;
  color: #2a2622;
}

.preview {
  grid-column: 3;
  min-width: 0;
  border: 1px solid #ece6dc;
  border-radius: 8px;
  background: #ffffff;
}

.preview-head {
  display: flex;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid #ece6dc;
  font-weight: 500;
}

.preview-date {
  color: #5c544b;
  font-weight: 400;
  font-size: 14px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

th,
td {
  padding: 9px 18px;
  text-align: left;
  border-bottom: 1px solid #f3eee6;
}

th {
  color: #5c544b;
  font-weight: 400;
}

tbody tr:last-child td {
  border-bottom: none;
}

.facts {
  padding-top: 8px;
  padding-bottom: 64px;
}

.facts p {
  margin: 0;
  color: #5c544b;
  text-wrap: pretty;
}

.fact-title {
  color: #2a2622;
  font-weight: 500;
}

/* Tablet and phone: one column, the table at full width under the
   buttons, the notes one under another. */
@media (max-width: 900px) {
  .site-header,
  .hero,
  .facts {
    padding-left: 24px;
    padding-right: 24px;
  }

  .hero,
  .facts {
    grid-template-columns: 1fr;
    row-gap: 24px;
  }

  .hero {
    padding-top: 40px;
    padding-bottom: 40px;
    row-gap: 40px;
  }

  .hero-text,
  .preview {
    grid-column: 1;
  }

  .hero-text {
    max-width: 600px;
  }

  .preview {
    max-width: 600px;
  }

  .facts p {
    max-width: 600px;
  }
}

@media (max-width: 480px) {
  .site-nav {
    gap: 4px 20px;
  }

  h1 {
    font-size: 32px;
  }

  th,
  td {
    padding: 9px 12px;
  }

  .preview-head {
    padding: 14px 12px;
  }
}

