  .hero,
  .facts {
    grid-template-columns: 1fr;
    row-gap: 24px;
  }

  .hero {
    padding-top: 40px;
    padding-bottom: 40px;
    row-gap: 40px;
  }

  .hero-text,
  .preview {
    grid-column: 1;
  }

  .closing {
    margin: 0 24px;
  }

  .hero-text {
    max-width: 600px;
  }

  .preview {
    max-width: 600px;
  }

  .facts p {
    max-width: 600px;
  }
}

@media (max-width: 480px) {
  .site-nav {
    gap: 4px 20px;
  }

  h1 {
    font-size: 32px;
  }

  th,
  td {
    padding: 9px 12px;
  }

  .preview-head {
    padding: 14px 12px;
  }
}

