h1 {
  margin: 0 0 16px;
  font-size: 40px;
  font-weight: 500;
  line-height: 1.15;
  text-wrap: balance;
}

.hero-text p {
  margin: 0 0 28px;
  color: #5c544b;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.button {
  display: inline-block;
  padding: 10px 18px;
  border-radius: 6px;
  text-decoration: none;
  font-size: 16px;
  white-space: nowrap;
}

.button-primary {
  border: 1px solid #8a3b24;
  background: #8a3b24;
  color: #ffffff;
  font-weight: 500;
