}

.preview-date {
  color: #5c544b;
  font-weight: 400;
  font-size: 14px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

th,
td {
  padding: 9px 18px;
  text-align: left;
  border-bottom: 1px solid #f3eee6;
}

th {
  color: #5c544b;
  font-weight: 400;
  white-space: nowrap;
}

tbody tr:last-child td {
  border-bottom: none;
}

.facts {
  grid-template-columns: repeat(3, 1fr);
  padding-top: 8px;
  padding-bottom: 80px;
}

